solutions.naive:
class Solution:
    def findErrorNums(self, nums: list[int]) -> list[int]:
        dup = miss = -1
        for x in range(1, len(nums)+1):
            c = sum(1 for y in nums if y == x)
            if c == 0:
                miss = x
            elif c == 2:
                dup = x
        return [dup, miss]

solutions.better:
class Solution:
    def findErrorNums(self, nums: list[int]) -> list[int]:
        seen, dup = set(), -1
        for x in nums:
            if x in seen:
                dup = x
            seen.add(x)
        n = len(nums)
        miss = n * (n + 1) // 2 - (sum(nums) - dup)
        return [dup, miss]

