class Solution:
    def findErrorNums(self, nums: list[int]) -> list[int]:
        dup = -1
        for x in nums:
            i = abs(x) - 1
            if nums[i] < 0:
                dup = abs(x)
            else:
                nums[i] = -nums[i]
        miss = next(i + 1 for i, x in enumerate(nums) if x > 0)
        return [dup, miss]

